<template><section class="panel live-timeline"><div class="timeline-heading"><h3>联动时间轴</h3><div class="timeline-options"><span class="badge blue"><Link2 :size="14"/>双路联动</span><RouterLink to="/playback" class="icon-button" title="打开录像回放" aria-label="打开录像回放"><Maximize :size="17"/></RouterLink></div></div>
<div class="timeline-toolbar"><RouterLink :to="{path:'/playback',query:{date:date}}" class="timeline-play" aria-label="打开录像回放" title="打开所选日期的录像回放"><Film :size="19"/></RouterLink><span class="timeline-clock">{{date===localDate()?timeOnly(now):date}}</span><span class="live-tag" :class="{inactive:date!==localDate()||!hasLive}"><i/>{{date!==localDate()?'历史录像':hasLive?'实时':'未接入'}}</span><input type="date" required aria-label="时间轴日期" v-model="date" @change="changeDate"/><RouterLink :to="{path:'/playback',query:{date}}" class="playback-link">检索录像 <ChevronRight :size="15"/></RouterLink></div>
<div class="timeline-axis"><span v-for="i in 6" :key="i">{{timeOnly(windowStart+(i-1)*windowLength/5)}}</span></div>
<div v-for="id in ids" :key="id" class="timeline-channel"><div class="channel-chip"><strong>{{id==='camera1'?'C1':'C2'}}</strong><span class="channel-label">{{cameras[id].label===id?'摄像机 '+(id==='camera1'?'1':'2'):cameras[id].label.replace(/^C[12][\s·]+/,'')}}</span></div><div class="timeline-rail"><RouterLink v-for="item in items.filter(m=>m.cameraId===id&&visible(m))" :key="item.id" :to="{path:'/playback',query:{date,id:item.id}}" class="recording-segment" :class="{unknown:item.duration<=0}" :style="segment(item)" :title="timeOnly(item.startedAt)+' · '+item.name+(item.duration<=0?' · 时长待解析':'')"/><i v-if="date===localDate()" class="timeline-playhead"/><span v-if="!items.some(m=>m.cameraId===id&&visible(m))" class="rail-label">{{loading?'正在读取…':loadError?'录像索引暂不可用':'此时间段暂无录像'}}</span></div></div>
</section></template>
<script setup lang="ts">
import{computed,onMounted,onUnmounted,ref}from'vue';import{Film,Link2,Maximize,ChevronRight}from'lucide-vue-next';import{http}from'@/api/http';import{localDate,timeOnly,type ProductMedia}from'@/lib/product-format';import type{CameraId,CameraRuntimeStatus}from'@/types/camera-types';
const props=defineProps<{cameras:Record<CameraId,CameraRuntimeStatus>}>();const hasLive=computed(()=>Object.values(props.cameras).some(c=>c.state==='streaming'));const ids:CameraId[]=['camera1','camera2'];const date=ref(localDate()),items=ref<ProductMedia[]>([]),now=ref(Date.now()),loading=ref(false),loadError=ref(false);let clock:ReturnType<typeof setInterval>,refresh:ReturnType<typeof setInterval>,stopped=false,request=0;
const today=computed(()=>{const value=new Date(now.value);return[value.getFullYear(),String(value.getMonth()+1).padStart(2,'0'),String(value.getDate()).padStart(2,'0')].join('-')});
const windowLength=computed(()=>date.value===today.value?600000:86400000);const windowStart=computed(()=>date.value===today.value?now.value-windowLength.value:new Date(date.value+'T00:00:00').getTime());
const visible=(m:ProductMedia)=>(m.duration>0?m.startedAt+m.duration*1000>windowStart.value:m.startedAt>=windowStart.value)&&m.startedAt<windowStart.value+windowLength.value;
const segment=(m:ProductMedia)=>{const start=Math.max(windowStart.value,m.startedAt),end=Math.min(windowStart.value+windowLength.value,m.startedAt+m.duration*1000);return{left:(start-windowStart.value)/windowLength.value*100+'%',width:Math.max(.3,(end-start)/windowLength.value*100)+'%'}};
function changeDate(){if(!/^\d{4}-\d{2}-\d{2}$/.test(date.value))date.value=today.value;void load()}
async function load(){const token=++request;loading.value=true;try{const{data}=await http.get('/media',{params:{date:date.value}});if(token===request&&!stopped){items.value=data.items.filter((m:ProductMedia)=>m.kind==='video'&&m.ready);loadError.value=false}}catch{if(token===request){items.value=[];loadError.value=true}}finally{if(token===request)loading.value=false}}
onMounted(()=>{void load();clock=setInterval(()=>now.value=Date.now(),1000);refresh=setInterval(load,10000)});onUnmounted(()=>{stopped=true;clearInterval(clock);clearInterval(refresh)});
</script>
<style scoped>
.live-timeline{position:relative;padding:0 20px 12px;overflow:hidden}.timeline-heading{position:absolute;left:22px;top:0;height:67px;display:flex;align-items:center;justify-content:space-between}.timeline-heading h3{margin:0;font-size:18px;font-weight:700;color:#141e2d}.timeline-options{display:none}.timeline-toolbar{height:67px;display:flex;align-items:center;gap:18px;border-bottom:1px solid #dce5f2;padding-left:132px}.timeline-play{background:var(--blue);width:38px;height:35px;display:grid;place-items:center;border-radius:7px;color:#fff}.timeline-clock{font-size:16px;font-weight:600;color:#202c42;font-variant-numeric:tabular-nums}.live-tag{display:flex;align-items:center;gap:6px;font-size:13px;color:#338557}.live-tag i{width:6px;height:6px;background:#42a271;border-radius:50%}.timeline-toolbar input{font-size:14px;border:1px solid #d3deef;border-radius:7px;background:#fbfcff;padding:5px 8px;margin-left:auto;color:#364760;width:147px;height:34px}.playback-link{display:flex;align-items:center;font-size:14px;color:#526987}.timeline-axis{display:flex;align-items:center;justify-content:space-between;font-size:14px;font-weight:500;color:#354660;height:40px;margin:0 0 4px 142px}.timeline-channel{display:flex;height:34px;align-items:center;gap:18px;font-size:14px}.channel-chip{width:124px;height:26px;display:flex;align-items:center;gap:8px;border-radius:5px;background:#e6ebf4;padding:3px 8px;color:#1b2638;flex-shrink:0}.timeline-channel strong{font-size:14px;font-weight:650;flex-shrink:0}.channel-label{min-width:0;font-size:12px;font-weight:600;white-space:nowrap;text-overflow:ellipsis;overflow:hidden}.timeline-rail{position:relative;flex:1;height:20px;background:repeating-linear-gradient(90deg,#f1f5fc 0,#f1f5fc calc(20% - 1px),#d7e1f1 20%);border-top:1px solid #d2dff0;border-bottom:1px solid #d2dff0;border-radius:3px}.recording-segment{position:absolute;top:0;height:18px;background:#a6cafd;border-radius:3px}.recording-segment:hover{background:#7eafff}.timeline-playhead{position:absolute;right:0;top:-6px;bottom:-6px;width:2px;background:#1677ff}.rail-label{position:absolute;left:12px;font-size:12px;line-height:18px;color:#899bb6}.live-tag.inactive{color:#8493ab}.live-tag.inactive i{background:#9baac0}.recording-segment.unknown{width:5px!important;background:#b49354}
@media(max-width:1300px){.timeline-toolbar{gap:12px}.timeline-axis{font-size:12px}.playback-link{font-size:12px}.timeline-toolbar input{width:138px;font-size:13px}.live-tag{display:none}}
@media(max-width:700px){.timeline-heading{position:static;height:42px}.timeline-toolbar{height:40px;padding-left:0;gap:9px}.timeline-axis{height:28px;margin-left:54px;font-size:10px}.timeline-toolbar input{width:132px;font-size:12px}.playback-link,.channel-label{display:none}.timeline-clock{font-size:14px}.live-timeline{padding:0 12px 12px}.channel-chip{width:36px}.timeline-channel{gap:18px}}
</style>
